
/* ===== Langues du site : bouton globe, menu, traduction intégrale =====
   Le bouton télécharger du bandeau est remplacé par un globe : au clic
   (ou au clavier) s'ouvre un menu esthétique des langues — drapeau SVG
   + nom de la langue dans sa propre langue. À la sélection, TOUT le
   site est traduit : les textes de la page de garde, du bandeau, des
   sept onglets de la carte (noms de plats et descriptions), des
   formules « Nos menus », et jusqu'aux libellés des médaillons et
   icônes des formules, recréés en SVG inline précisément pour que
   leur texte soit traduisible (les PNG d'origine gravient leur texte
   dans l'image). Restent en français : les noms propres (vins,
   châteaux, cocktails signature, adresse), les prix et leur format.
   Principe « propre et sûr » : le texte français EST la clé. Au
   chargement, chaque nœud texte du document est recensé avec son
   original ; appliquer une langue remplace le contenu par la
   traduction si elle existe, sinon conserve l'original — aucun
   élément ne peut être perdu, et repasser en français restaure
   l'original exact. La langue est mémorisée (localStorage) et
   forçable par l'URL (?lang=en), la carte A4 / impression reste en
   français (mode carte-doc ignoré), et le mouvement réduit n'est pas
   concerné (aucune animation obligatoire). */
